import { Component, OnInit } from '@angular/core';
import { switchAll } from 'rxjs/operators';
import {HomeService} from '../home.service'
import Swal from 'sweetalert2';
import { NavController } from '@ionic/angular';

@Component({
  selector: 'app-changepassword',
  templateUrl: './changepassword.page.html',
  styleUrls: ['./changepassword.page.scss'],
})
export class ChangepasswordPage implements OnInit {
  isTextFieldType: boolean;
  isTextField: any;
  isText: any;
  user1:any={};
togglePasswordFieldType(){
  this.isTextFieldType=!this.isTextFieldType;
}
togglePasswordField(){
  this.isTextField=!this.isTextField;
}
 constructor(private user :HomeService,private navCtrl:NavController) {

   }

  ngOnInit() {
   this.user1=JSON.stringify( localStorage.token)
  }
  save(old_password,new_password){
    let userdata={old_password:old_password,new_password:new_password,token:this.user1};
    this.user.changepassword(userdata).subscribe((res:any) =>{
      console.log(res);
      if(res.message== "Password updated successfully"){
        Swal.fire("Password updated successfully");
        this.navCtrl.navigateBack('/login');
      }
    })
  }

}
